//! ↩️ move-mesh leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfMesh;
use crate::artifacts::gltf::schema::mutations::move_mesh::mutation::{validate, GltfMoveMeshPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{meshes_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.move-mesh.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfMoveMeshInverseOperation { Insert { position: usize, item: GltfMesh }, Delete { index: usize, removed: GltfMesh }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfMoveMeshInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfMoveMeshPayload, pub operation: GltfMoveMeshInverseOperation }
async fn operation(payload: &GltfMoveMeshPayload, base: &GltfSnapshot) -> GltfMoveMeshInverseOperation { GltfMoveMeshInverseOperation::Move { index: payload.position, position: payload.index } }
async fn touched_paths(payload: &GltfMoveMeshPayload) -> Vec<String> { vec![format!("document/meshes/{}", payload.index), format!("document/meshes/{}", payload.position)] }
pub async fn validate_inverse(inverse: &GltfMoveMeshInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub async fn apply_inverse(inverse: &GltfMoveMeshInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfMoveMeshInverseOperation::Insert { position, .. } if *position > after.document.meshes.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/meshes", "position must be within the collection")), GltfMoveMeshInverseOperation::Delete { index, .. } if *index >= after.document.meshes.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/meshes", "index must address an item")), GltfMoveMeshInverseOperation::Move { index, position } if *index >= after.document.meshes.len() || *position >= after.document.meshes.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/meshes", "indices must address items")), GltfMoveMeshInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.meshes.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.meshes.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/meshes", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfMoveMeshInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Meshes, &Change::Insert(*position))?; next.document.meshes.insert(*position, item.clone());  }, GltfMoveMeshInverseOperation::Delete { index, .. } => { meshes_op(&mut next, GltfTopLevelFamily::Meshes, *index, None, None)?;  }, GltfMoveMeshInverseOperation::Move { index, position } => { meshes_op(&mut next, GltfTopLevelFamily::Meshes, *index, Some(*position), None)?;  }, GltfMoveMeshInverseOperation::Reorder { order } => { meshes_op(&mut next, GltfTopLevelFamily::Meshes, order[0], None, Some(order))?;  } } Ok(next) }
pub async fn encode(inverse: &GltfMoveMeshInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub async fn derive(payload: &GltfMoveMeshPayload, base: &GltfSnapshot) -> Result<GltfMoveMeshInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfMoveMeshInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
